sql_text:
SELECT W."PlannedQty", W."BaseQtyNum", W."BaseQtyDen", O."PlannedQty"
            FROM "TELCHI"."WOR1" W JOIN "TELCHI"."OWOR" O ON O."DocEntry"=W."DocEntry"
